mapper.sql:
WHERE IS_DELETED = 0

    AND TENANT_ID = #{param.tenantId,jdbcType=BIGINT}


    AND BOOK_ID = #{param.bookId,jdbcType=BIGINT}


    AND PARAM_CODE LIKE '%' || #{param.paramCode,jdbcType=VARCHAR} || '%'


    AND PARAM_NAME LIKE '%' || #{param.paramName,jdbcType=VARCHAR} || '%'


    AND CATEGORY_CODE = #{param.categoryCode,jdbcType=VARCHAR}


    AND PARAM_TYPE = #{param.paramType,jdbcType=VARCHAR}


    AND IS_ENABLED = #{param.isEnabled,jdbcType=INTEGER}

mapper.select:
SELECT 
FROM (
    SELECT 
    FROM TBL_FINANCE_SYSTEM_PARAMS
    WHERE IS_DELETED = 0
    AND PARAM_CODE = #{paramCode,jdbcType=VARCHAR}

        AND TENANT_ID = #{tenantId,jdbcType=BIGINT}


        AND BOOK_ID = #{bookId,jdbcType=BIGINT}

    ORDER BY CREATE_TIME DESC
)
WHERE ROWNUM = 1

SELECT 
FROM TBL_FINANCE_SYSTEM_PARAMS
WHERE IS_DELETED = 0
AND CATEGORY_CODE = #{categoryCode,jdbcType=VARCHAR}
AND IS_ENABLED = 1

    AND TENANT_ID = #{tenantId,jdbcType=BIGINT}


    AND BOOK_ID = #{bookId,jdbcType=BIGINT}

ORDER BY CREATE_TIME DESC

SELECT COUNT(1)
FROM TBL_FINANCE_SYSTEM_PARAMS
WHERE IS_DELETED = 0
AND PARAM_CODE = #{paramCode,jdbcType=VARCHAR}

    AND TENANT_ID = #{tenantId,jdbcType=BIGINT}


    AND BOOK_ID = #{bookId,jdbcType=BIGINT}


    AND ID != #{excludeId,jdbcType=BIGINT}
